import math

def cosine(a, b):
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if not na or not nb:
        return 0.0
    return round(sum(x * y for x, y in zip(a, b)) / (na * nb), 4)

